/**
 * Challenger UI-M5 Empirical Adversarial Verification Harness
 * Focus: Physical TV Deployment, On-Device Proxy, 1080p Playback, Seeking & Remote Stress
 * Target: LG 32LR686BPSA (webOS 8.5.0, 192.168.1.15:9922)
 */

const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

const CONFIG = {
  tvIp: '192.168.1.15',
  sshPort: '9922',
  sshUser: 'prisoner',
  sshKey: '/home/prem/.ssh/lg-tv_webos_rsa',
  sshKeyFallback: '/home/prem/.ssh/lg-tv_webos_decrypted',
  devtoolsPort: 9998,
  aresDevice: 'lg-tv',
  servicePort: 8088,
  appId: 'com.cinejoy.tv',
  serviceId: 'com.cinejoy.tv.service',
  maxRssMb: 50.0,
  minFreeRamMb: 200.0
};

const C = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  red: '\x1b[31m',
  cyan: '\x1b[36m',
  dim: '\x1b[2m'
};

function banner(msg) {
  const line = '═'.repeat(72);
  console.log(`\n${C.cyan}${C.bold}${line}`);
  console.log(`   ${msg}`);
  console.log(`${line}${C.reset}\n`);
}

function pass(name, detail) {
  console.log(`  ${C.green}✔ PASS${C.reset} ${name} ${detail ? C.dim + '(' + detail + ')' + C.reset : ''}`);
}

function fail(name, err) {
  console.error(`  ${C.red}✖ FAIL${C.reset} ${name}`);
  if (err) console.error(`    ${C.red}${err.stack || err}${C.reset}`);
}

function sleep(ms) {
  return new Promise(r => setTimeout(r, ms));
}

function execSsh(cmd) {
  const activeKey = fs.existsSync(CONFIG.sshKey) ? CONFIG.sshKey : CONFIG.sshKeyFallback;
  return execSync(
    `ssh -tt -p ${CONFIG.sshPort} -i ${activeKey} -o HostKeyAlgorithms=+ssh-rsa -o PubkeyAcceptedKeyTypes=+ssh-rsa -o StrictHostKeyChecking=no -o ConnectTimeout=10 ${CONFIG.sshUser}@${CONFIG.tvIp} "${cmd.replace(/"/g, '\\"')}"`,
    { encoding: 'utf8', timeout: 30000 }
  );
}

class CdpClient {
  constructor(wsUrl) {
    this.wsUrl = wsUrl;
    this.ws = null;
    this.id = 1;
    this.pending = new Map();
  }

  connect() {
    return new Promise((resolve, reject) => {
      this.ws = new WebSocket(this.wsUrl);
      this.ws.onopen = () => resolve();
      this.ws.onerror = err => reject(err);
      this.ws.onmessage = event => {
        try {
          const msg = JSON.parse(event.data);
          if (msg.id && this.pending.has(msg.id)) {
            const { resolve: res, reject: rej } = this.pending.get(msg.id);
            this.pending.delete(msg.id);
            if (msg.error) rej(new Error(msg.error.message || JSON.stringify(msg.error)));
            else res(msg.result);
          }
        } catch (e) {
          console.error('CDP parse error:', e);
        }
      };
    });
  }

  send(method, params = {}) {
    return new Promise((resolve, reject) => {
      if (!this.ws || this.ws.readyState !== 1) {
        return reject(new Error('WebSocket not connected'));
      }
      const msgId = this.id++;
      this.pending.set(msgId, { resolve, reject });
      this.ws.send(JSON.stringify({ id: msgId, method, params }));
    });
  }

  async evaluate(expression, awaitPromise = true) {
    const res = await this.send('Runtime.evaluate', {
      expression,
      awaitPromise,
      returnByValue: true
    });
    if (res.exceptionDetails) {
      throw new Error(
        res.exceptionDetails.exception
          ? (res.exceptionDetails.exception.description || res.exceptionDetails.exception.value)
          : 'Evaluation exception'
      );
    }
    return res.result ? res.result.value : undefined;
  }

  close() {
    if (this.ws) {
      try { this.ws.close(); } catch (_) {}
      this.ws = null;
    }
  }
}

async function runChallengerHarness() {
  banner('CHALLENGER UI-M5 EMPIRICAL ADVERSARIAL VERIFICATION');
  const results = [];
  let cdp = null;

  async function check(num, name, fn) {
    const t0 = Date.now();
    try {
      const detail = await fn();
      const elapsed = Date.now() - t0;
      pass(`[${num}] ${name}`, `${elapsed}ms${detail ? ' | ' + detail : ''}`);
      results.push({ num, name, passed: true, elapsed, detail });
    } catch (err) {
      const elapsed = Date.now() - t0;
      fail(`[${num}] ${name}`, err);
      results.push({ num, name, passed: false, elapsed, error: err.message });
      throw err;
    }
  }

  try {
    // Check 1: Target Device Profile
    await check(1, 'Physical TV Hardware & SDK Match', async () => {
      const out = execSync(`ares-device -i -d ${CONFIG.aresDevice}`, { encoding: 'utf8' });
      if (!out.includes('32LR686BPSA') || !out.includes('8.5.0') || !out.includes('13.50.44')) {
        throw new Error(`Device profile mismatch:\n${out}`);
      }
      return 'LG 32LR686BPSA (webOS 8.5.0, FW 13.50.44)';
    });

    // Check 2: Service Process & Luna Status
    let servicePid = null;
    await check(2, 'Background Node 12 Service & Luna Status', async () => {
      const lunaOut = execSsh(`luna-send-pub -i -n 1 luna://${CONFIG.serviceId}/status '{}'`);
      const statusRes = JSON.parse(lunaOut.slice(lunaOut.indexOf('{'), lunaOut.lastIndexOf('}') + 1));
      if (statusRes.returnValue !== true || statusRes.status !== 'running') {
        throw new Error(`Service not running cleanly: ${JSON.stringify(statusRes)}`);
      }
      const pidOut = execSsh(`pidof ${CONFIG.serviceId}`);
      servicePid = (pidOut.match(/\b\d+\b/) || [])[0];
      if (!servicePid) throw new Error('Could not find PID of running service');
      return `PID: ${servicePid}, Uptime: ${Math.round(statusRes.uptime)}s, RSS: ${(statusRes.rssBytes / 1048576).toFixed(2)} MB`;
    });

    // Check 3: Loopback Proxy Health & Zero-Leak Resilience
    await check(3, 'Loopback Proxy Port 8088 & /health Verification', async () => {
      const healthRaw = execSsh(`curl -s http://127.0.0.1:${CONFIG.servicePort}/health`);
      const health = JSON.parse(healthRaw);
      if (health.status !== 'ok' || health.mode !== 'on-device-service') {
        throw new Error(`Health status invalid: ${healthRaw}`);
      }
      return `Mode: ${health.mode}, Port: ${health.port}`;
    });

    // Check 4: HTTP 206 Partial Content Range Streaming Over Proxy
    await check(4, 'HTTP Range Streaming (206 Partial Content) & Header Bypassing', async () => {
      // Stream Fight Club 1080p init segment or seg-v0
      const curlHeaders = execSsh(
        `curl -sI -H "Range: bytes=0-2047" "http://127.0.0.1:${CONFIG.servicePort}/hls/proxy?url=https%3A%2F%2Flightspeed.st%2Fhls%2Fce181615-7914-4b8f-927c-eff91e855a39%2F1%2F1080p%2Fseg-v0.png"`
      );
      if (!curlHeaders.includes('206 Partial Content')) {
        throw new Error(`Expected HTTP 206 Partial Content, got:\n${curlHeaders}`);
      }
      if (!curlHeaders.includes('Content-Range: bytes 0-2047/')) {
        throw new Error(`Invalid Content-Range header:\n${curlHeaders}`);
      }
      return 'HTTP 206 OK, bytes 0-2047 verified';
    });

    // Check 5: Multi-Title Cryptographic Stream Resolution (Movie & Series)
    await check(5, 'Multi-Title WASM crush.wasm + AES-256-GCM Resolution', async () => {
      // Title A: Movie (Fight Club, 550)
      const movieResRaw = execSsh(
        `curl -s "http://127.0.0.1:${CONFIG.servicePort}/api/stream?tmdbId=550&type=movie&server=secret"`
      );
      const movieRes = JSON.parse(movieResRaw);
      if (!movieRes.success || !movieRes.streamUrl) {
        throw new Error(`Movie resolution failed: ${movieResRaw}`);
      }

      // Title B: TV Show (Game of Thrones S01E01, 1399)
      const tvResRaw = execSsh(
        `curl -s "http://127.0.0.1:${CONFIG.servicePort}/api/stream?tmdbId=1399&type=tv&season=1&episode=1&server=secret"`
      );
      const tvRes = JSON.parse(tvResRaw);
      if (!tvRes.success || !tvRes.streamUrl) {
        throw new Error(`TV resolution failed: ${tvResRaw}`);
      }

      return `Movie Subtitles: ${movieRes.subtitles.length}, TV Subtitles: ${tvRes.subtitles.length}`;
    });

    // Check 6: 1080p Rendition Availability & Master Playlist Inspection
    await check(6, '1080p FHD M3U8 Master Rendition & Media Playlist Verification', async () => {
      const masterM3u8 = execSsh(
        `curl -s "http://127.0.0.1:${CONFIG.servicePort}/hls/proxy?url=https%3A%2F%2Flightspeed.st%2Fhls%2Fce181615-7914-4b8f-927c-eff91e855a39%2F1%2Fmaster.m3u8"`
      );
      if (!masterM3u8.includes('RESOLUTION=1920x1080')) {
        throw new Error('Master playlist lacks 1920x1080 rendition');
      }
      // Check 1080p playlist itself
      const fhdM3u8 = execSsh(
        `curl -s "http://127.0.0.1:${CONFIG.servicePort}/hls/proxy?url=https%3A%2F%2Flightspeed.st%2Fhls%2Fce181615-7914-4b8f-927c-eff91e855a39%2F1%2F1080p%2Fplaylist.m3u8"`
      );
      if (!fhdM3u8.includes('#EXT-X-TARGETDURATION')) {
        throw new Error('1080p media playlist malformed');
      }
      return '1920x1080 rendition verified in master & media playlists';
    });

    // Check 7: CDP Connection & Live Player Playback Assertion
    await check(7, 'Live HTML5 <video> Playback Progression & Buffer Verification', async () => {
      const pages = await fetch(`http://${CONFIG.tvIp}:${CONFIG.devtoolsPort}/json`).then(r => r.json());
      const target = pages.find(p => p.url && p.url.includes(CONFIG.appId));
      if (!target) throw new Error('Could not find com.cinejoy.tv in DevTools targets');

      cdp = new CdpClient(target.webSocketDebuggerUrl);
      await cdp.connect();
      await cdp.send('Runtime.enable');

      // Switch to player view and load stream
      await cdp.evaluate(`(() => {
        CinejoyApp.switchView("player");
        return PlayerController.loadStream({ tmdbId: 550, title: "Fight Club", type: "movie" });
      })()`);

      // Wait for playback ready
      let ready = false;
      for (let i = 0; i < 20; i++) {
        await sleep(1000);
        const status = await cdp.evaluate(`(() => {
          const v = document.getElementById("main-video-player");
          return { readyState: v.readyState, paused: v.paused, currentTime: v.currentTime };
        })()`);
        if (status.readyState >= 3) {
          ready = true;
          break;
        }
      }
      if (!ready) throw new Error('Video did not achieve readyState >= 3');

      // Unpause if paused
      await cdp.evaluate('PlayerController.play()');

      // Measure playback progression over 4 seconds
      const t0 = await cdp.evaluate(`(() => {
        const v = document.getElementById("main-video-player");
        return {
          currentTime: v.currentTime,
          duration: v.duration,
          bufferedEnd: v.buffered.length > 0 ? v.buffered.end(v.buffered.length - 1) : 0,
          videoWidth: v.videoWidth,
          videoHeight: v.videoHeight
        };
      })()`);

      await sleep(4000);

      const t1 = await cdp.evaluate(`(() => {
        const v = document.getElementById("main-video-player");
        return {
          currentTime: v.currentTime,
          paused: v.paused,
          readyState: v.readyState,
          bufferedEnd: v.buffered.length > 0 ? v.buffered.end(v.buffered.length - 1) : 0
        };
      })()`);

      if (t1.currentTime <= t0.currentTime) {
        throw new Error(`Video did not advance: ${t0.currentTime} -> ${t1.currentTime}`);
      }
      if (t1.paused) throw new Error('Video became paused unexpectedly');
      if (t1.bufferedEnd <= t1.currentTime) {
        throw new Error('Video buffer underrun: buffer behind playhead');
      }

      return `Progression: ${t0.currentTime.toFixed(2)}s -> ${t1.currentTime.toFixed(2)}s | Buffer Ahead: ${(t1.bufferedEnd - t1.currentTime).toFixed(2)}s`;
    });

    // Check 8: Adversarial Rapid Seeking & Recovery Stress
    await check(8, 'Adversarial Rapid Seeking Stress (+15s, +15s, -15s)', async () => {
      const tStart = await cdp.evaluate('document.getElementById("main-video-player").currentTime');

      // Perform 2 rapid forward seeks
      await cdp.evaluate('PlayerController.seekBy(15)');
      await sleep(200);
      await cdp.evaluate('PlayerController.seekBy(15)');

      // Wait up to 6s for seek to settle
      let settled = false;
      let finalState = null;
      for (let i = 0; i < 15; i++) {
        await sleep(400);
        finalState = await cdp.evaluate(`(() => {
          const v = document.getElementById("main-video-player");
          return { readyState: v.readyState, seeking: v.seeking, currentTime: v.currentTime };
        })()`);
        if (!finalState.seeking && finalState.readyState >= 3) {
          settled = true;
          break;
        }
      }

      if (!settled) throw new Error(`Rapid seek did not settle: ${JSON.stringify(finalState)}`);
      if (finalState.currentTime < tStart + 20) {
        throw new Error(`Seek did not advance properly: ${tStart.toFixed(2)}s -> ${finalState.currentTime.toFixed(2)}s`);
      }

      return `Recovered cleanly to ${finalState.currentTime.toFixed(2)}s (readyState: ${finalState.readyState})`;
    });

    // Check 9: Remote Back Key & Focus Hierarchy Stress
    await check(9, 'Remote Back Key (Keycode 461) Navigation & Teardown', async () => {
      // Send Back Key event (461)
      await cdp.evaluate(`(() => {
        const ev = new KeyboardEvent("keydown", { keyCode: 461, bubbles: true });
        window.dispatchEvent(ev);
      })()`);

      await sleep(1000);

      const navState = await cdp.evaluate(`({
        currentView: CinejoyApp.currentView,
        playerState: PlayerController.state,
        videoPaused: document.getElementById("main-video-player").paused,
        focusedElement: document.activeElement ? (document.activeElement.id || document.activeElement.className) : null
      })`);

      if (navState.currentView === 'player' && navState.playerState === 'PLAYING') {
        throw new Error(`Back key failed to exit player: ${JSON.stringify(navState)}`);
      }

      return `Exited player -> View: ${navState.currentView}, Player State: ${navState.playerState}`;
    });

    // Check 10: Service Persistence & Physical Memory Profiling
    await check(10, 'Service Zero-Crash Persistence & TV RAM Budget Audit', async () => {
      const pidOut = execSsh(`pidof ${CONFIG.serviceId}`);
      const currentPid = (pidOut.match(/\b\d+\b/) || [])[0];
      if (currentPid !== servicePid) {
        throw new Error(`Service PID changed! (Initial: ${servicePid}, Current: ${currentPid})`);
      }

      const procStatus = execSsh(`cat /proc/${servicePid}/status`);
      const freeMem = execSsh('free -m');

      const statusMap = {};
      procStatus.split('\n').forEach(l => {
        const parts = l.split(':');
        if (parts.length >= 2) statusMap[parts[0].trim()] = parts.slice(1).join(':').trim();
      });

      const vmRssMb = parseInt(statusMap['VmRSS'] || '0', 10) / 1024;
      if (vmRssMb > CONFIG.maxRssMb) {
        throw new Error(`VmRSS ${vmRssMb.toFixed(2)} MB exceeded budget of ${CONFIG.maxRssMb} MB`);
      }

      let availableRamMb = 0;
      freeMem.split('\n').forEach(l => {
        if (l.startsWith('Mem:')) {
          const cols = l.trim().split(/\s+/);
          availableRamMb = parseInt(cols[cols.length - 1], 10);
        }
      });

      if (availableRamMb < CONFIG.minFreeRamMb) {
        throw new Error(`Available RAM ${availableRamMb} MB below ${CONFIG.minFreeRamMb} MB limit`);
      }

      return `VmRSS: ${vmRssMb.toFixed(2)} MB (< 50MB) | Available RAM: ${availableRamMb} MB (> 200MB) | Zero PID restart`;
    });

    if (cdp) cdp.close();

    banner('ALL 10 EMPIRICAL ADVERSARIAL CHALLENGES PASSED (100% SUCCESS)');
    console.log('Empirical verdict: APPROVE');

  } catch (err) {
    if (cdp) cdp.close();
    banner('CHALLENGE HARNESS FAILED');
    console.error('Failure details:', err);
    process.exit(1);
  }
}

runChallengerHarness().catch(err => {
  console.error('Fatal:', err);
  process.exit(1);
});

